ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS codice_fiscale text, ADD COLUMN IF NOT EXISTS nome_coach text, ADD COLUMN IF NOT EXISTS cognome_coach text, ADD COLUMN IF NOT EXISTS telefono text, ADD COLUMN IF NOT EXISTS provincia text, ADD COLUMN IF NOT EXISTS partita_iva text, ADD COLUMN IF NOT EXISTS codice_affiliazione text;
CREATE UNIQUE INDEX IF NOT EXISTS profiles_codice_fiscale_unique ON public.profiles (upper(regexp_replace(codice_fiscale, '\s+', '', 'g'))) WHERE codice_fiscale IS NOT NULL AND btrim(codice_fiscale) <> '';
ALTER TABLE public.atleti ADD COLUMN IF NOT EXISTS coach text, ADD COLUMN IF NOT EXISTS serie text, ADD COLUMN IF NOT EXISTS categoria text, ADD COLUMN IF NOT EXISTS totale_match integer DEFAULT 0, ADD COLUMN IF NOT EXISTS certificato_path text, ADD COLUMN IF NOT EXISTS certificato_rilascio date, ADD COLUMN IF NOT EXISTS certificato_scadenza date, ADD COLUMN IF NOT EXISTS certificato_tipo text, ADD COLUMN IF NOT EXISTS certificato_disciplina text;
ALTER TABLE public.eventi ADD COLUMN IF NOT EXISTS organizzatore text, ADD COLUMN IF NOT EXISTS apertura_iscrizioni timestamptz, ADD COLUMN IF NOT EXISTS discipline_ammesse text[], ADD COLUMN IF NOT EXISTS serie_ammesse text[], ADD COLUMN IF NOT EXISTS categorie_ammesse text[], ADD COLUMN IF NOT EXISTS limite_partecipanti integer, ADD COLUMN IF NOT EXISTS blocca_certificato_scaduto boolean DEFAULT false, ADD COLUMN IF NOT EXISTS originale_richiesto boolean DEFAULT false;
ALTER TABLE public.iscrizioni ADD COLUMN IF NOT EXISTS snapshot_nome text, ADD COLUMN IF NOT EXISTS snapshot_cognome text, ADD COLUMN IF NOT EXISTS snapshot_data_nascita date, ADD COLUMN IF NOT EXISTS snapshot_sesso text, ADD COLUMN IF NOT EXISTS snapshot_team text, ADD COLUMN IF NOT EXISTS snapshot_coach text, ADD COLUMN IF NOT EXISTS snapshot_peso_kg numeric, ADD COLUMN IF NOT EXISTS snapshot_serie text, ADD COLUMN IF NOT EXISTS snapshot_categoria text, ADD COLUMN IF NOT EXISTS snapshot_totale_match integer, ADD COLUMN IF NOT EXISTS senior_17 boolean DEFAULT false;
UPDATE public.iscrizioni i SET snapshot_nome = a.nome, snapshot_cognome = a.cognome, snapshot_data_nascita = a.data_nascita, snapshot_sesso = a.sesso, snapshot_team = a.nome_societa, snapshot_coach = a.coach, snapshot_peso_kg = a.peso_kg, snapshot_serie = a.serie, snapshot_categoria = a.categoria, snapshot_totale_match = coalesce(a.totale_match, a.vittorie+a.sconfitte+a.pareggi), disciplina = coalesce(i.disciplina,a.disciplina) FROM public.atleti a WHERE i.atleta_id = a.id AND i.snapshot_nome IS NULL;
CREATE TABLE public.match_cards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evento_id uuid NOT NULL REFERENCES public.eventi(id) ON DELETE CASCADE, rosso_id uuid NOT NULL REFERENCES public.iscrizioni(id) ON DELETE CASCADE, blu_id uuid NOT NULL REFERENCES public.iscrizioni(id) ON DELETE CASCADE, numero integer, score integer, stato text NOT NULL DEFAULT 'proposta', pool_id uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT match_atleti_diversi CHECK (rosso_id <> blu_id));
GRANT SELECT ON public.match_cards TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.match_cards TO authenticated; GRANT ALL ON public.match_cards TO service_role;
ALTER TABLE public.match_cards ENABLE ROW LEVEL SECURITY;
CREATE POLICY "match pubblicati visibili" ON public.match_cards FOR SELECT TO anon, authenticated USING (stato = 'pubblicato' AND EXISTS (SELECT 1 FROM public.eventi e WHERE e.id = evento_id AND e.stato IN ('pubblicato','concluso')));
CREATE POLICY "admin gestisce match" ON public.match_cards FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.pools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evento_id uuid NOT NULL REFERENCES public.eventi(id) ON DELETE CASCADE, numero integer, iscrizione_ids uuid[] NOT NULL DEFAULT '{}', score integer, stato text NOT NULL DEFAULT 'proposta', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.pools TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.pools TO authenticated; GRANT ALL ON public.pools TO service_role;
ALTER TABLE public.pools ENABLE ROW LEVEL SECURITY;
CREATE POLICY "pool pubblicati visibili" ON public.pools FOR SELECT TO anon, authenticated USING (stato = 'pubblicato' AND EXISTS (SELECT 1 FROM public.eventi e WHERE e.id = evento_id AND e.stato IN ('pubblicato','concluso')));
CREATE POLICY "admin gestisce pool" ON public.pools FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
ALTER TABLE public.match_cards ADD CONSTRAINT match_cards_pool_id_fkey FOREIGN KEY (pool_id) REFERENCES public.pools(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS match_cards_evento_idx ON public.match_cards(evento_id); CREATE INDEX IF NOT EXISTS pools_evento_idx ON public.pools(evento_id);
CREATE OR REPLACE FUNCTION public.validate_fight_registration() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE e public.eventi%ROWTYPE; a public.atleti%ROWTYPE; years integer; BEGIN SELECT * INTO e FROM public.eventi WHERE id = NEW.evento_id; SELECT * INTO a FROM public.atleti WHERE id = NEW.atleta_id; IF e.id IS NULL OR a.id IS NULL THEN RAISE EXCEPTION 'Evento o atleta non trovato'; END IF; IF NEW.societa_id IS DISTINCT FROM a.societa_id THEN RAISE EXCEPTION 'Atleta non appartenente alla società'; END IF; IF NOT public.has_role(auth.uid(), 'admin') THEN IF e.stato NOT IN ('aperto', 'iscrizioni aperte') OR now() > e.fine_iscrizioni OR (e.apertura_iscrizioni IS NOT NULL AND now() < e.apertura_iscrizioni) THEN RAISE EXCEPTION 'Le iscrizioni sono chiuse'; END IF; IF TG_OP = 'UPDATE' AND (NEW.stato IS DISTINCT FROM OLD.stato OR NEW.evento_id IS DISTINCT FROM OLD.evento_id OR NEW.societa_id IS DISTINCT FROM OLD.societa_id OR NEW.atleta_id IS DISTINCT FROM OLD.atleta_id) THEN RAISE EXCEPTION 'Solo un amministratore può cambiare stato o titolarità'; END IF; IF e.limite_partecipanti IS NOT NULL AND TG_OP = 'INSERT' AND (SELECT count(*) FROM public.iscrizioni WHERE evento_id = NEW.evento_id) >= e.limite_partecipanti THEN RAISE EXCEPTION 'Limite partecipanti raggiunto'; END IF; IF e.blocca_certificato_scaduto AND (a.certificato_scadenza IS NULL OR a.certificato_scadenza < e.data_evento) THEN RAISE EXCEPTION 'Certificato medico non valido per la data della gara'; END IF; END IF; years := CASE WHEN a.data_nascita IS NULL THEN NULL ELSE extract(year FROM age(e.data_evento, a.data_nascita))::int END; IF NEW.senior_17 AND years IS DISTINCT FROM 17 THEN RAISE EXCEPTION 'L’opzione Senior è riservata agli atleti di 17 anni'; END IF; IF NEW.senior_17 THEN NEW.snapshot_categoria := 'SENIOR'; END IF; IF TG_OP = 'INSERT' THEN NEW.snapshot_nome := coalesce(NEW.snapshot_nome, a.nome); NEW.snapshot_cognome := coalesce(NEW.snapshot_cognome, a.cognome); NEW.snapshot_data_nascita := coalesce(NEW.snapshot_data_nascita, a.data_nascita); NEW.snapshot_sesso := coalesce(NEW.snapshot_sesso, a.sesso); NEW.snapshot_team := coalesce(NEW.snapshot_team, a.nome_societa); NEW.snapshot_coach := coalesce(NEW.snapshot_coach, a.coach); NEW.snapshot_peso_kg := coalesce(NEW.snapshot_peso_kg, a.peso_kg); NEW.snapshot_serie := coalesce(NEW.snapshot_serie, a.serie); NEW.snapshot_categoria := coalesce(NEW.snapshot_categoria, a.categoria); NEW.snapshot_totale_match := coalesce(NEW.snapshot_totale_match, a.totale_match, 0); NEW.disciplina := coalesce(NEW.disciplina, a.disciplina); END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_fight_registration_trigger BEFORE INSERT OR UPDATE ON public.iscrizioni FOR EACH ROW EXECUTE FUNCTION public.validate_fight_registration();
CREATE OR REPLACE FUNCTION public.validate_fight_registration_delete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.has_role(auth.uid(), 'admin') AND NOT EXISTS (SELECT 1 FROM public.eventi WHERE id = OLD.evento_id AND stato IN ('aperto','iscrizioni aperte') AND fine_iscrizioni > now()) THEN RAISE EXCEPTION 'Le iscrizioni sono chiuse'; END IF; RETURN OLD; END $$;
CREATE TRIGGER validate_fight_registration_delete_trigger BEFORE DELETE ON public.iscrizioni FOR EACH ROW EXECUTE FUNCTION public.validate_fight_registration_delete();